--
-- Table structure for table `messages`
--

DROP TABLE IF EXISTS `messages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `messages` (
  `Id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ZoneId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `FirstName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `LastName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `Email` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CountryId` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `TraditionId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `SubmittedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `UpdatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `PublishedAt` datetime(6) DEFAULT NULL,
  `LastModeratedAt` datetime(6) DEFAULT NULL COMMENT 'Latest moderation timestamp',
  `IsSafe` tinyint(1) DEFAULT NULL,
  `ModerationModel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ModerationStatus` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Pending / Passed / Flagged / Failed',
  `ModerationAttemptCount` int NOT NULL DEFAULT '0' COMMENT 'Total moderation attempts',
  `Status` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Pending / Approved / Rejected',
  `ReviewedBy` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FK to applicationusers table',
  `ReviewComments` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ReviewedAt` datetime(6) DEFAULT NULL,
  `Allows_Marketing_Emails` tinyint DEFAULT '0',
  `Terms_Accepted` tinyint DEFAULT '0',
  `Post_Anonymously` tinyint DEFAULT '0',
  PRIMARY KEY (`Id`),
  KEY `IDX_Messages_ZoneId` (`ZoneId`),
  KEY `IDX_Messages_Status` (`Status`),
  KEY `IDX_Messages_CreatedAt` (`SubmittedAt`),
  KEY `FK_Messages_Users` (`ReviewedBy`),
  CONSTRAINT `FK_Messages_Users` FOREIGN KEY (`ReviewedBy`) REFERENCES `applicationusers` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_Messages_Zones` FOREIGN KEY (`ZoneId`) REFERENCES `zones` (`Id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

