CREATE TABLE `moderationhistories` (
  `Id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `TriggeredBy` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'System' COMMENT 'System / Admin',
  `TriggeredByUserId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FK to applicationusers table; NULL for System',
  `MessageId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ModerationModelId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `IsSafe` tinyint(1) NOT NULL,
  `RawResult` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `CreatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`Id`),
  KEY `IDX_ModerationHistories_MessageId` (`MessageId`),
  KEY `FK_ModerationHistories_Users` (`TriggeredByUserId`),
  CONSTRAINT `FK_ModerationHistories_Messages` FOREIGN KEY (`MessageId`) REFERENCES `messages` (`Id`) ON DELETE CASCADE,
  CONSTRAINT `FK_ModerationHistories_Users` FOREIGN KEY (`TriggeredByUserId`) REFERENCES `applicationusers` (`Id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
